root=p/'sherlock-js/results/glyph-caller-flags-30';root.mkdir(exist_ok=True);(root/'glyph-caller-flags-30.asm').write_text('\n'.join(lines)+'\n');(root/'listing-verification.json').write_text(json.dumps(dict(roundtrip_equal=True,instructions=count,bytes_roundtripped=total,regions=[dict(start=f'{a:04X}',end_exclusive=f'{b:04X}',kind=k,label=l,atlas_priority=158)for a,b,k,l in regions]),indent=2)+'\n');print(count,total)
